gsap.registerPlugin(ScrollTrigger);

/* ---------- global cursor trail (fine red web-thread dots) ---------- */
(function(){
  if (!window.matchMedia('(hover:hover)').matches) return; // skip on touch devices
  var dot = document.createElement('div');
  dot.className = 'cursor-dot';
  document.body.appendChild(dot);
  gsap.set(dot, {opacity:0.85});
  var dotX = gsap.quickTo(dot, 'x', {duration:0.15, ease:'power2.out'});
  var dotY = gsap.quickTo(dot, 'y', {duration:0.15, ease:'power2.out'});
  var lastSpawn = 0;
  window.addEventListener('mousemove', function(e){
    dotX(e.clientX); dotY(e.clientY);
    var now = Date.now();
    if (now - lastSpawn > 55){
      lastSpawn = now;
      var trail = document.createElement('div');
      trail.className = 'web-trail-dot';
      trail.style.left = e.clientX + 'px';
      trail.style.top = e.clientY + 'px';
      document.body.appendChild(trail);
      gsap.to(trail, {opacity:0, scale:0.2, duration:0.7, ease:'power1.out', onComplete:function(){ trail.remove(); }});
    }
  });
})();

/* ---------- click-to-shoot web line (fixed full-page SVG layer) ---------- */
var webShotSvg = document.createElementNS('http://www.w3.org/2000/svg','svg');
webShotSvg.setAttribute('style','position:fixed;inset:0;width:100vw;height:100vh;pointer-events:none;z-index:997;');
document.body.appendChild(webShotSvg);
function shootWeb(x, y){
  var svgNS = 'http://www.w3.org/2000/svg';
  var originX = window.innerWidth * 0.5, originY = window.innerHeight;
  var midX = (originX + x) / 2 + (Math.random()*80 - 40);
  var midY = (originY + y) / 2 - 40;
  var path = document.createElementNS(svgNS,'path');
  var d = 'M' + originX + ',' + originY + ' Q' + midX + ',' + midY + ' ' + x + ',' + y;
  path.setAttribute('d', d);
  path.setAttribute('stroke', 'rgba(154,27,47,0.6)');
  path.setAttribute('stroke-width', '1.5');
  path.setAttribute('fill', 'none');
  webShotSvg.appendChild(path);
  var len = path.getTotalLength();
  path.style.strokeDasharray = len;
  path.style.strokeDashoffset = len;
  gsap.to(path, {
    strokeDashoffset: 0, duration: 0.35, ease: 'power2.out',
    onComplete: function(){
      gsap.to(path, {opacity:0, duration:0.6, delay:0.15, onComplete:function(){ path.remove(); }});
    }
  });
}

/* ---------- spider web generator (pure geometry, no character art) ---------- */
function buildWeb(container, size, strands){
  const ns = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(ns,'svg');
  svg.setAttribute('viewBox', '0 0 '+size+' '+size);
  const cx = size/2, cy = size/2, r = size/2 - 4;
  const g = document.createElementNS(ns,'g');
  g.setAttribute('id','webGroup');
  for(let i=0;i<strands;i++){
    const angle = (i/strands)*Math.PI*2;
    const x2 = cx + Math.cos(angle)*r, y2 = cy + Math.sin(angle)*r;
    const line = document.createElementNS(ns,'line');
    line.setAttribute('x1',cx);line.setAttribute('y1',cy);
    line.setAttribute('x2',x2);line.setAttribute('y2',y2);
    line.setAttribute('stroke-width','0.8');
    g.appendChild(line);
  }
  const rings = 5;
  for(let ring=1;ring<=rings;ring++){
    const rr = (r/rings)*ring;
    let d = '';
    for(let i=0;i<=strands;i++){
      const angle = (i/strands)*Math.PI*2;
      const wob = (i%2===0? 1: 0.94);
      const x = cx + Math.cos(angle)*rr*wob;
      const y = cy + Math.sin(angle)*rr*wob;
      d += (i===0?'M':'L') + x.toFixed(1) + ' ' + y.toFixed(1) + ' ';
    }
    const path = document.createElementNS(ns,'path');
    path.setAttribute('d', d);
    path.setAttribute('stroke-width','0.7');
    g.appendChild(path);
  }
  svg.appendChild(g);
  container.appendChild(svg);
  return svg;
}
document.querySelectorAll('.web-deco').forEach(function(el, i){
  buildWeb(el, 400, i%2===0?9:11);
});
