/* ---------- GSAP context: entrance ---------- */
let ctx = gsap.context(function(){

  const tl = gsap.timeline({defaults:{ease:'power3.out'}});

  tl.from('#heroHi', {opacity:0, x:-40, duration:0.6})
    .from('#heroHeading', {opacity:0, x:-90, duration:0.9, ease:'power4.out'}, '-=0.3')
    .from('#heroRole', {opacity:0, x:-40, duration:0.6}, '-=0.4')
    .from('#heroLede', {opacity:0, y:20, duration:0.7}, '-=0.3')
    .from('#heroCta .btn', {opacity:0, y:16, duration:0.6, stagger:0.1}, '-=0.4')
    .from('#heroGraphic', {opacity:0, scale:0.85, rotateY:25, duration:1, ease:'power3.out'}, '-=0.9');

  // continuous ambient: subtle idle float
  gsap.to('#heroGraphic', {
    y: -8, duration: 3, yoyo:true, repeat:-1, ease:'sine.inOut', delay: 1.6
  });

  /* ---- 3D tilt parallax on the hero graphic, follows the cursor ---- */
  const heroGraphic = document.getElementById('heroGraphic');
  const heroSection = document.getElementById('hero');
  if (heroGraphic && heroSection && window.matchMedia('(hover:hover)').matches){
    const rotX = gsap.quickTo(heroGraphic, 'rotateX', {duration:0.6, ease:'power3.out'});
    const rotY = gsap.quickTo(heroGraphic, 'rotateY', {duration:0.6, ease:'power3.out'});
    heroSection.addEventListener('mousemove', function(e){
      const r = heroGraphic.getBoundingClientRect();
      const px = (e.clientX - r.left) / r.width - 0.5;
      const py = (e.clientY - r.top) / r.height - 0.5;
      rotY(px * 16);
      rotX(py * -16);
    });
    heroSection.addEventListener('mouseleave', function(){ rotX(0); rotY(0); });
  }

  /* ---- magnetic buttons ---- */
  document.querySelectorAll('.magnetic').forEach(function(btn){
    const mx = gsap.quickTo(btn, 'x', {duration:0.4, ease:'power3.out'});
    const my = gsap.quickTo(btn, 'y', {duration:0.4, ease:'power3.out'});
    btn.addEventListener('mousemove', function(e){
      const r = btn.getBoundingClientRect();
      mx((e.clientX - r.left - r.width/2) * 0.35);
      my((e.clientY - r.top - r.height/2) * 0.35);
    });
    btn.addEventListener('mouseleave', function(){ mx(0); my(0); });
  });

  /* ---- click-to-shoot a web line (hero easter egg) ---- */
  if (heroSection){
    heroSection.addEventListener('click', function(e){
      if (e.target.closest('.btn') || e.target.closest('a')) return;
      shootWeb(e.clientX, e.clientY);
    });
  }

  // about paragraph 3D reveal
  gsap.utils.toArray('.ab-p').forEach(function(p, i){
    gsap.fromTo(p, {y:40, opacity:0, rotationX:-45}, {
      y:0, opacity:1, rotationX:0, duration:0.9, ease:'back.out(1.6)',
      scrollTrigger:{trigger:p, start:'top 88%'}, delay:i*0.05
    });
  });
  gsap.from('.stat', {
    opacity:0, y:24, duration:0.7, stagger:0.12,
    scrollTrigger:{trigger:'.stat-row', start:'top 90%'}
  });

  // education timeline — each row sweeps in from the left, one after another
  gsap.utils.toArray('.edu-item').forEach(function(item, i){
    gsap.from(item, {
      opacity:0, x:-90, duration:0.7, ease:'power4.out', delay:i*0.05,
      scrollTrigger:{trigger:item, start:'top 90%'}
    });
  });
  gsap.from('#pillRow .pill', {
    scale:0.5, opacity:0, y:20, duration:0.6, stagger:0.08, ease:'back.out(2)',
    scrollTrigger:{trigger:'#pillRow', start:'top 90%'}
  });
  gsap.utils.toArray('#pillRow .pill').forEach(function(p,i){
    gsap.to(p, {y:-5, duration: 1.6+Math.random(), yoyo:true, repeat:-1, ease:'sine.inOut', delay: i*0.15});
  });

  // section headers — left-to-right clip-path wipe on the heading, eyebrow slides in first, rule sweeps last
  gsap.utils.toArray('.section-head').forEach(function(h){
    var eyebrow = h.querySelector('.eyebrow');
    var heading = h.querySelector('h2');
    var rule = h.querySelector('.rule');
    var tlHead = gsap.timeline({scrollTrigger:{trigger:h, start:'top 85%'}});
    if (eyebrow) tlHead.from(eyebrow, {opacity:0, x:-40, duration:0.55, ease:'power3.out'});
    if (heading) tlHead.fromTo(heading,
      {opacity:0, x:-50, clipPath:'inset(0 100% 0 0)'},
      {opacity:1, x:0, clipPath:'inset(0 0% 0 0)', duration:0.85, ease:'power4.out'}, '-=0.25');
    if (rule) tlHead.fromTo(rule, {scaleX:0}, {scaleX:1, duration:0.6, ease:'power3.out'}, '-=0.35');
  });

  // skills cards — alternate slide from left / right with a light tilt
  gsap.utils.toArray('#skillsGrid .skill-card').forEach(function(card, i){
    gsap.from(card, {
      opacity:0, x: i % 2 === 0 ? -70 : 70, rotateZ: i % 2 === 0 ? -3 : 3,
      duration:0.75, ease:'power3.out',
      scrollTrigger:{trigger:card, start:'top 92%'}
    });
  });

  // project cards — alternate slide from left / right, staggered by row
  gsap.utils.toArray('#projectGrid .project-card').forEach(function(card, i){
    gsap.from(card, {
      opacity:0, x: i % 2 === 0 ? -90 : 90, y:20, rotateZ: i % 2 === 0 ? -2 : 2,
      duration:0.85, ease:'power4.out',
      scrollTrigger:{trigger:card, start:'top 90%'}
    });
  });

  // internship cards
  gsap.utils.toArray('#expGrid .cert-card').forEach(function(card, i){
    gsap.from(card, {
      opacity:0, x: i % 2 === 0 ? -60 : 60, duration:0.6, ease:'power3.out',
      scrollTrigger:{trigger:card, start:'top 92%'}
    });
  });

  // certificate cards — alternate slide from left / right
  gsap.utils.toArray('#certGrid .cert-card').forEach(function(card, i){
    gsap.from(card, {
      opacity:0, x: i % 2 === 0 ? -55 : 55, duration:0.55, ease:'power3.out',
      scrollTrigger:{trigger:card, start:'top 93%'}
    });
  });

  // achievements list — alternating left/right entrance
  gsap.utils.toArray('.ach-list li').forEach(function(li, i){
    gsap.from(li, {
      opacity:0, x: i % 2 === 0 ? -50 : 50, duration:0.65, ease:'power3.out',
      scrollTrigger:{trigger:li, start:'top 94%'}
    });
  });
  gsap.from('.interest-cloud .pill', {
    opacity:0, scale:0.6, x:-20, duration:0.5, stagger:0.04, ease:'back.out(2)',
    scrollTrigger:{trigger:'.interest-cloud', start:'top 88%'}
  });

  // platform cards — swoop in left to right across the row
  gsap.from('.platform-card', {
    opacity:0, x:-60, duration:0.6, stagger:0.1, ease:'power3.out',
    scrollTrigger:{trigger:'.platform-grid', start:'top 88%'}
  });

  // sign-off: image slides in from the left, text follows
  gsap.from('.signoff-image', {
    opacity:0, x:-70, duration:0.8, ease:'power3.out',
    scrollTrigger:{trigger:'.signoff-wrap', start:'top 85%'}
  });
  gsap.from('.signoff-text > *', {
    opacity:0, x:40, duration:0.7, stagger:0.1, ease:'power3.out',
    scrollTrigger:{trigger:'.signoff-wrap', start:'top 82%'}
  });

  // footer
  gsap.from('footer h2, .footer-links li', {
    opacity:0, y:22, duration:0.7, stagger:0.06,
    scrollTrigger:{trigger:'footer', start:'top 90%'}
  });

}, document.body);

/* ---------- Node/Express contact form ---------- */
(function(){
  const form = document.getElementById('contactForm');
  const status = document.getElementById('contactStatus');
  const submit = document.getElementById('contactSubmit');

  if (!form) return;

  form.addEventListener('submit', async function(e){
    e.preventDefault();

    const name = document.getElementById('name').value.trim();
    const email = document.getElementById('email').value.trim();
    const message = document.getElementById('message').value.trim();

    if (!name || !email || !message) {
      status.textContent = 'Please fill in all fields.';
      return;
    }

    submit.disabled = true;
    status.textContent = 'Sending...';

    try {
      const response = await fetch('/contact', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({name, email, message})
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.message || 'Failed to send message.');
      }

      status.textContent = data.message;
      form.reset();
    } catch (error) {
      console.error(error);
      status.textContent = error.message || 'Unable to send message.';
    } finally {
      submit.disabled = false;
    }
  });
})();
